import React from 'react';
import { useProfilePicture } from '../utils/profilePicture';

// The player's profile picture (Round 34) as a small round identity
// image. Renders NOTHING when no picture is set — every surface that
// includes this component keeps its exact pre-round rendering until
// the player chooses a picture, and returns to it when the picture
// is removed. Demo players never render through here: this is the
// local player's own chosen identity image only, stored on-device.
export const PlayerAvatar: React.FC<{
  size?: number;
  style?: React.CSSProperties;
  testId?: string;
}> = ({ size = 32, style, testId = 'player-avatar' }) => {
  const picture = useProfilePicture();
  if (!picture) return null;
  return (
    <img
      data-testid={testId}
      src={picture}
      alt="Your profile picture"
      style={{
        width: size,
        height: size,
        borderRadius: '50%',
        objectFit: 'cover',
        flexShrink: 0,
        ...style,
      }}
    />
  );
};

export default PlayerAvatar;
