import React, { useState } from 'react';
import {
  Box,
  Button,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Typography,
} from '@mui/material';
import { useNavigate } from 'react-router-dom';
import { WELCOME_DISMISSED_EVENT } from '../utils/tour';

// First-arrival ecosystem welcome (Round 27, Eddie 2026-11-18).
//
// Eddie's rule: when a player first arrives, they are told UP
// FRONT that GLACER is an ecosystem that rewards participating —
// the house model is the welcome, not fine print discovered
// later. Design of record: glacer-wallet-design-v1.md, v5
// addendum — the copy below is Eddie's current wording VERBATIM
// (headline, body, small print), and the same message lives
// permanently on the Wallet page's house-model card so it can be
// re-read anytime.
//
// Placement: APP SHELL (rendered in App.tsx inside the Router),
// not Home-only. First arrival is defined by ARRIVING, not by
// which page a shared link lands on — a first tap on /venues,
// /map or /wallet is a first arrival too, and a Home-only welcome
// would silently skip those players. The dialog overlays whatever
// page booted underneath (deep links load normally; dismissing
// reveals them untouched) and writes NO state besides its own
// seen-flag, so it can never trap or reroute anyone.
//
// Shown exactly once per device: localStorage `glacer-welcome-seen`.
// Per-account once-ness arrives with the real backend (Phase 2) —
// no account logic here. DEMO framing matches the Wallet page's:
// the copy describes the real design; the chip keeps it honest
// that no payment rail is connected yet.
export const WELCOME_SEEN_KEY = 'glacer-welcome-seen';

const WELCOME_HEADLINE = 'GLACER gives back.';
const WELCOME_BODY =
  "This isn't just a game — it's an ecosystem that rewards you for participating. Battle, walk, explore, meet people: playing earns you Points. Points turn into perks or Real Bucks — real money you can spend here or cash out. And every month, GLACER shares part of what it earns with the players who showed up. Your share is our way of saying thanks for helping GLACER grow.";
const WELCOME_SMALL_PRINT =
  'Real Bucks are worth $1.25 when you spend them in GLACER, or $1.00 cashed out. Cash out unlocks once your balance reaches $100.';

const FirstArrivalWelcome: React.FC = () => {
  const navigate = useNavigate();
  const [open, setOpen] = useState<boolean>(() => {
    try {
      return !localStorage.getItem(WELCOME_SEEN_KEY);
    } catch {
      // Storage unavailable (private mode, blocked cookies): treat
      // as seen rather than risk re-showing on every navigation.
      return false;
    }
  });

  if (!open) return null;

  const dismiss = () => {
    try {
      localStorage.setItem(WELCOME_SEEN_KEY, '1');
    } catch {
      // The flag is best-effort; dismissing must always work.
    }
    setOpen(false);
    // Round 32: every exit path funnels through here, so this is
    // the one place that announces the welcome is resolved — the
    // first-run tour sequences itself after the greeting from
    // this event instead of stacking on top of it.
    try {
      window.dispatchEvent(new Event(WELCOME_DISMISSED_EVENT));
    } catch {
      // Announcement is best-effort; dismissing must always work.
    }
  };

  const seeWallet = () => {
    dismiss();
    navigate('/wallet');
  };

  return (
    <Dialog
      open={open}
      onClose={dismiss}
      fullWidth
      maxWidth="xs"
      data-testid="welcome-dialog"
      aria-labelledby="welcome-headline"
    >
      <DialogTitle>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
          <Typography
            id="welcome-headline"
            variant="h6"
            component="span"
            data-testid="welcome-headline"
          >
            {WELCOME_HEADLINE}
          </Typography>
          <Chip
            label="DEMO"
            size="small"
            color="warning"
            sx={{ fontWeight: 'bold' }}
            data-testid="welcome-demo-chip"
          />
        </Box>
      </DialogTitle>
      <DialogContent>
        <Typography variant="body1" data-testid="welcome-body">
          {WELCOME_BODY}
        </Typography>
        {/* The money facts ride on the SAME screen, readable —
            never buried (v5 addendum: "same screen, not buried"). */}
        <Typography variant="body2" sx={{ mt: 2 }} data-testid="welcome-smallprint">
          {WELCOME_SMALL_PRINT}
        </Typography>
      </DialogContent>
      <DialogActions>
        <Button variant="outlined" onClick={seeWallet} data-testid="welcome-wallet-button">
          See your wallet
        </Button>
        <Button variant="contained" onClick={dismiss} data-testid="welcome-start-button">
          Start playing
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default FirstArrivalWelcome;
