import React, { useEffect } from 'react';
import { useLocation } from 'react-router-dom';

// Scroll reset on navigation (Round 10 add-on, Eddie 2026-11-17:
// "When I push the Navidex tab, I need to go to the top of the
// Navidex page"). An SPA keeps the window's scroll position across
// route changes, so tapping a tab used to land mid-page wherever
// the previous page left off. Every pathname change now lands at
// the TOP of the destination page — one mechanism at the router
// level, so every surface (bottom tab bar, top-bar menu, in-page
// links) gets it consistently.
//
// One deliberate exemption: the venue-focus deep link. Tapping a
// venue notice stashes the venue id in sessionStorage
// ('glacer-venue-focus', data/venueBuzz.ts) and navigates to the
// World Map, whose mount effect consumes it and flies to + scrolls
// to that venue. Resetting scroll for that navigation would fight
// the landing, so when the handoff is pending this reset stands
// down — it only PEEKS at the key; RealmMap remains the consumer.
export const ScrollToTop: React.FC = () => {
  const { pathname } = useLocation();
  useEffect(() => {
    try {
      if (sessionStorage.getItem('glacer-venue-focus')) return;
    } catch {
      // Storage unavailable — reset normally.
    }
    window.scrollTo(0, 0);
  }, [pathname]);
  return null;
};
