import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Box } from '@mui/material';
import ModelCanvas from './ModelCanvas';
import ElementalAmbience, { useAmbientActive } from './ElementalAmbience';
import { NavitarArtImg } from './NavitarArtImg';
import { fxColors } from '../utils/attackFx';
import { motionSignatureFor } from '../utils/motionSignature';
import { elementEmoji, modelPresentationFor } from '../utils/navitarArt';
import { resolveShowcaseModel, type ResolvedShowcaseModel } from '../utils/modelResolution';
import { getCare, type StageCare } from '../utils/training';

// THE HOME STAGE (Round 35.5, Eddie 2026-11-19 ~08:37 PT): the
// Home hero card's art slot is a living 3D STAGE for the ACTIVE
// navitar — the same presentation family as the Navidex Stage
// (bare contact shadow inside ModelCanvas — the podium disc
// retired in Round 36.5 — the fighter's saved crystal tint on
// the model, the floor glow under it, in-scene yaw sway,
// Realm Elements only while the model stands). Eddie's
// direction replaces the flat
// portrait that used to fill this slot; it does NOT move any
// choosing here — the stage is display only, and adopting /
// choosing still live in the Navidex alone (the tidy law).
//
// SEAMLESS + LAZY (the standing rules): Home's first paint
// never waits on this stage. The portrait is the rest state —
// the exact image the card showed before this round — and the
// canvas mounts only after the page has painted (a rAF gate on
// mount), so the fighter's GLB is fetched after first paint,
// never before. When the model stands, the two layers cross-
// fade in place: no blank frame, no spinner, no loading card.
// Only the ACTIVE fighter's model is ever resolved or fetched
// (resolveShowcaseModel — the same chain Stroll's companion
// uses). A fighter with no model keeps its portrait forever,
// and a model that fails to load falls back to the portrait
// permanently — a model is never faked.
//
// Colours (Round 36.5): the Home stage's colour doorway is
// REMOVED with the whole accent colour system (Eddie,
// 2026-11-19 — the one colour system is the Modify octagon
// pad's crystal tints in the Navidex). The stage still wears
// the fighter's saved crystal tint — the Modify pad owns it,
// and care changes arrive live via the glacer-care-changed
// event, so a tint saved in the Navidex is the tint Home
// wears. The standing base is a BARE contact shadow now (the
// podium disc is retired on this stage too); the floor glow
// wears its CSS element default again.

interface ModelCarrierLike {
  name: string;
  element: string;
  modelUrl?: string;
  modelZoom?: number;
}

interface HomeNavitarStageProps {
  navitar: ModelCarrierLike & {
    id: string;
    imageUrl?: string;
  };
  businessNavitars: ModelCarrierLike[];
  // The resolved portrait art for this navitar (Home's existing
  // resolveNavitarArt result) — the stage's rest state.
  art: string | null;
}

export const HomeNavitarStage: React.FC<HomeNavitarStageProps> = ({
  navitar,
  businessNavitars,
  art,
}) => {
  const frameRef = useRef<HTMLDivElement>(null);
  const ambientActive = useAmbientActive(frameRef);
  const model: ResolvedShowcaseModel | null = useMemo(
    () => resolveShowcaseModel(navitar, businessNavitars),
    [navitar, businessNavitars]
  );
  const sig = useMemo(
    () => motionSignatureFor(navitar.name, navitar.element),
    [navitar.name, navitar.element]
  );
  const fx = fxColors(navitar.element);

  const [care, setCare] = useState<StageCare>(() => getCare(navitar.name));
  const [mountCanvas, setMountCanvas] = useState(false);
  const [standing, setStanding] = useState(false);
  const [failed, setFailed] = useState(false);

  // A different active fighter restages from the portrait: the
  // canvas remounts under the new fighter's key and the flip
  // happens again when ITS model stands.
  useEffect(() => {
    setCare(getCare(navitar.name));
    setStanding(false);
    setFailed(false);
  }, [navitar.id, navitar.name]);

  // Care written elsewhere (the Navidex Modify pad's tint
  // save, Feed/Train on the Stage) lands here live — one
  // record, two stages, never a stale tint.
  useEffect(() => {
    const onCareChanged = (e: Event) => {
      const name = (e as CustomEvent<{ name?: string }>).detail?.name;
      if (name === navitar.name) setCare(getCare(navitar.name));
    };
    window.addEventListener('glacer-care-changed', onCareChanged);
    return () => window.removeEventListener('glacer-care-changed', onCareChanged);
  }, [navitar.name]);

  // The lazy gate: the canvas (and with it the GLB fetch) waits
  // until after Home's first paint.
  useEffect(() => {
    if (!model) return;
    let raf2 = 0;
    const raf1 = requestAnimationFrame(() => {
      raf2 = requestAnimationFrame(() => setMountCanvas(true));
    });
    return () => {
      cancelAnimationFrame(raf1);
      if (raf2) cancelAnimationFrame(raf2);
    };
  }, [model, navitar.id]);

  const presentation = model ? modelPresentationFor(model.modelUrl) : null;

  return (
    <Box
      ref={frameRef}
      data-testid="home-stage"
      data-standing={standing ? 'true' : 'false'}
      data-modeled={model ? 'true' : 'false'}
      sx={{ position: 'absolute', inset: 0 }}
    >
      {/* Floor glow — the stage's ground light, wearing its
          CSS element default (Round 36.5: the accent system
          that used to tint it is removed). */}
      <div className="glacer-stage-floor" />
      {/* REST STATE — the portrait, exactly the image this slot
          carried before the stage arrived. It stays while the
          model travels and forever when there is no model (or
          the model failed); once the model stands it fades out
          under the canvas in the same frame. */}
      <Box
        data-testid="home-stage-portrait"
        sx={{
          position: 'absolute',
          inset: 0,
          opacity: standing ? 0 : 1,
          transition: 'opacity 0.45s ease',
          pointerEvents: 'none',
        }}
      >
        {art ? (
          <NavitarArtImg
            src={art}
            alt={`${navitar.name} art`}
            element={navitar.element}
            style={{
              position: 'absolute',
              inset: 0,
              width: '100%',
              height: '100%',
              objectFit: 'cover',
              display: 'block',
            }}
          />
        ) : (
          <Box
            sx={{
              position: 'absolute',
              inset: 0,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontSize: '4.5rem',
            }}
          >
            {elementEmoji(navitar.element)}
          </Box>
        )}
      </Box>
      {/* THE MODEL — mounted only after first paint, invisible
          until it stands (ModelCanvas onLoaded), then the flip:
          canvas fades in over the portrait in the same frame.
          Presentation law, same as the Navidex Stage: upright,
          in-scene yaw sway only, no orbit, podium disc +
          contact shadow, grounded at min.y. */}
      {mountCanvas && model && !failed && (
        <Box
          data-testid="home-stage-canvas"
          sx={{
            position: 'absolute',
            inset: 0,
            opacity: standing ? 1 : 0,
            transition: 'opacity 0.45s ease',
            filter: care.tint,
            pointerEvents: standing ? 'auto' : 'none',
          }}
        >
          <ModelCanvas
            key={navitar.id}
            modelUrl={model.modelUrl}
            zoom={model.modelZoom ?? navitar.modelZoom}
            grounded
            yawAmpDeg={sig.style === 'spin' ? 30 : 12}
            yawPeriodS={sig.style === 'spin' ? sig.durationS : Math.max(6, sig.durationS)}
            yawPhaseS={sig.delayS}
            // Standing base (Round 36.5): bare contact shadow
            // only — the podium disc is retired on this stage,
            // and the tint is the element's own.
            baseTint={fx.primary}
            bareShadow
            ripple={navitar.element === 'water'}
            rotationY={presentation?.rotationY}
            sinkFrac={presentation?.sinkFrac}
            onLoaded={() => setStanding(true)}
            onError={() => setFailed(true)}
          />
        </Box>
      )}
      {/* Realm Elements (Round 30 rule): the elemental weather
          belongs to the loaded 3D character — it mounts only
          while the model stands. */}
      {standing && (
        <div
          style={{
            position: 'absolute',
            inset: 0,
            zIndex: 3,
            pointerEvents: 'none',
          }}
        >
          <ElementalAmbience
            key={`${navitar.name}-${navitar.element}`}
            element={navitar.element}
            seed={navitar.name}
            variant="stage"
            active={ambientActive}
          />
        </div>
      )}
      {/* (Round 36.5: the colour bar that mounted here is
          REMOVED with the accent system — Home keeps the 3D
          stage, the portrait rest state and its Battle button
          only. Crystal tints live in the Navidex Modify pad.) */}
    </Box>
  );
};

export default HomeNavitarStage;
