// then the name map. The circle is 72px — big enough to read as the
// character itself, not a dot or a pin.
function companionIcon(navitar: { name: string; element: string; imageUrl?: string }) {
  // Marker-size art (Round 36.9 Part 7d): the circle draws at 72 px.
  const art = markerArtUrl(resolveNavitarArt(navitar.imageUrl, navitar.name));
  const color = elementColor(navitar.element);
  const inner = art
    ? `<img src="${art}" alt="" style="width:100%;height:100%;object-fit:cover;display:block;" />`
    : `<div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;font-size:36px;">${elementEmoji(navitar.element)}</div>`;
  return L.divIcon({
    className: 'glacer-companion-marker',
    html:
      `<div style="width:72px;height:72px;border-radius:50%;border:4px solid ${color};` +
      `overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.6);background:#121212;">${inner}</div>` +
      `<div style="text-align:center;font-size:11px;font-weight:bold;color:#fff;` +
      `text-shadow:0 1px 3px rgba(0,0,0,0.8);margin-top:2px;">${escapeHtml(navitar.name)}</div>`,
    iconSize: [72, 90],
    iconAnchor: [36, 36],
    popupAnchor: [0, -36],
  });
}

// Companion marker, positioned by SCREEN distance — not by degrees.
// A degree offset is ~8px on screen at zoom 11 and ~64px at zoom 14,
// so no degree offset can look right at both zooms: the old 0.007°
// offset let the 72px navitar circle completely cover the 44px player
// disc at the zoom-11 overview (verified in a real browser). The
// companion instead sits a fixed COMPANION_GAP_PX from the player,
// southeast (down-right on screen), recomputed from the map's own
// projection whenever the zoom or the player's position changes. The
// gap is 64px centre-to-centre: the player disc is 44px (22px radius)
// and the navitar circle is 72px (36px radius), so the pair clears by
// 6px and still reads as walking together at every zoom. Must live
// inside <MapContainer> (useMap); Leaflet zoom/pan events do not
// re-render React on their own, so the position lives in state.
// Round 8: the state no longer SNAPS to the recomputed spot — it
// eases toward it (see the trailing interval inside), so the
// companion visibly follows a step or two behind the player.
const COMPANION_GAP_PX = 64;
// Southeast at 45°: each axis gets gap / √2 so the diagonal screen
// distance is exactly COMPANION_GAP_PX.
const COMPANION_OFFSET_PX = COMPANION_GAP_PX / Math.SQRT2;

function CompanionMarker({
  playerPos,
  navitar,
  checkedInVenue,
}: {
  playerPos: [number, number];
  navitar: {
    name: string;
    element: string;
    imageUrl?: string;
    level: number;
    hp: number;
    maxHp: number;
  };
  checkedInVenue: DemoVenue | null;
}) {
  const map = useMap();
  const toCompanionLatLng = useCallback(
    (pos: [number, number]): [number, number] => {
      const point = map.latLngToLayerPoint(L.latLng(pos));
      const shifted = point.add(L.point(COMPANION_OFFSET_PX, COMPANION_OFFSET_PX));
      const ll = map.layerPointToLatLng(shifted);
      return [ll.lat, ll.lng];
    },
    [map]
  );
  const [companionPos, setCompanionPos] = useState<[number, number]>(() =>
    toCompanionLatLng(playerPos)
  );
  // TRAILING (Round 8, Eddie 2026-11-16: the navitar should "travel
  // the map as you walk, just following you"): the companion no
  // longer snaps to its offset the instant the player moves — it
  // EASES toward the offset spot, a step or two behind, and catches
  // up when the player stops. No teleport-pop. The target lives in
  // a ref (recomputed from the map's own projection whenever the
  // player moves or the view changes); a short interval walks the
  // marker toward it and then CLEARS ITSELF once it arrives
  // (Round 36.9 Part 7c), so an idle map doesn't churn.
  const targetRef = React.useRef<[number, number]>(companionPos);
  // Round 36.9 Part 7c (battery audit §7 #4): the glide interval
  // CLEARS ITSELF once the companion has settled on its target
  // and re-arms when the target moves (player moves, zoom/pan
  // recomputes the offset). The shipped pattern fired every
  // 120 ms forever — the highest idle CPU measured on any
  // screen (12.5% in the audit) — even though its updater
  // already detected arrival. Position lives in a ref so the
  // interval can read/settle without a state-driven effect.
  const posRef = React.useRef<[number, number]>(companionPos);
  const glideRef = React.useRef<number | null>(null);
  const startGlide = React.useCallback(() => {
    if (glideRef.current !== null) return;
    glideRef.current = window.setInterval(() => {
      const prev = posRef.current;
      const tgt = targetRef.current;
      const dLat = tgt[0] - prev[0];
      const dLng = tgt[1] - prev[1];
      if (Math.abs(dLat) < 1e-7 && Math.abs(dLng) < 1e-7) {
        // Settled: stand down until the target moves again.
        if (glideRef.current !== null) {
          window.clearInterval(glideRef.current);
          glideRef.current = null;
        }
        return;
      }
      const next: [number, number] = [prev[0] + dLat * 0.22, prev[1] + dLng * 0.22];
      posRef.current = next;
      setCompanionPos(next);
    }, 120);
  }, []);
  useEffect(() => {
    targetRef.current = toCompanionLatLng(playerPos);
    startGlide();
  }, [toCompanionLatLng, playerPos, startGlide]);
  useEffect(() => {
    const update = () => {
      targetRef.current = toCompanionLatLng(playerPos);
      startGlide();
    };
    map.on('zoomend', update);
    map.on('moveend', update);
    return () => {
      map.off('zoomend', update);
      map.off('moveend', update);
    };
  }, [map, toCompanionLatLng, playerPos, startGlide]);
  useEffect(() => {
    startGlide();
    return () => {
      if (glideRef.current !== null) {
        window.clearInterval(glideRef.current);
        glideRef.current = null;
      }
    };
  }, [startGlide]);
  // Memoized for the same reason as cachedIcon above: a fresh icon
  // object per render makes Leaflet swap the marker's DOM node.
  const icon = React.useMemo(
    () => companionIcon(navitar),
    [navitar.name, navitar.element, navitar.imageUrl]
  );
  return (
    <Marker position={companionPos} icon={icon} zIndexOffset={0}>
      <Popup>
        <div>
          <strong>
            {elementEmoji(navitar.element)} {navitar.name}
          </strong>
          <br />
          Your companion · Lv. {navitar.level} · {navitar.element}
          <br />
          HP {navitar.hp}/{navitar.maxHp}
          {checkedInVenue && (
            <>
              <br />
              Checked in at {checkedInVenue.name}
            </>
          )}
        </div>
      </Popup>
    </Marker>
  );
}

// Round art thumb for the companion panel (collapsed chip + expanded
