import React from 'react';
import {
  Box,
  Button,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Typography,
} from '@mui/material';
import type { VenuePerson } from '../data/venues';
import { PersonStatusChip } from './NetworkingStatus';
import { NavitarArtImg } from './NavitarArtImg';
import { elementColor, elementEmoji, resolveNavitarArt } from '../utils/navitarArt';

// A person's profile (Step 4, 2026-11-14): everywhere the app links
// a person — Networking matches, the Profile friends list — their
// profile is now viewable: who they are, why they're here, and the
// navitar at their side. Read-only and honest: it shows exactly the
// demo persona data the game already carries (vibe, presence,
// interests, their navitar's level/element/skills) — nothing is
// invented, and opening it changes nothing (meeting still starts
// with an icebreaker or a challenge, chosen elsewhere).
export const PersonaProfileDialog: React.FC<{
  person: VenuePerson | null;
  venueName?: string | null;
  onClose: () => void;
}> = ({ person, venueName, onClose }) => {
  const art = person ? resolveNavitarArt(person.navitarImage, person.navitarName) : null;
  return (
    <Dialog open={person !== null} onClose={onClose} maxWidth="xs" fullWidth>
      {person && (
        <>
          <DialogTitle>
            {person.name}
            {venueName ? (
              <Typography variant="body2" color="text.secondary">
                at {venueName}
              </Typography>
            ) : null}
          </DialogTitle>
          <DialogContent>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap', mb: 1.5 }}>
              <PersonStatusChip status={person.networkingStatus} />
              {person.visibility === 'business' && (
                <Chip label="Business contacts only" size="small" color="primary" />
              )}
              {person.visibility === 'friends' && (
                <Chip label="Friends only" size="small" color="primary" />
              )}
            </Box>
            <Typography variant="body1" paragraph>
              {person.vibe}
            </Typography>
            {person.businessName && (
              <Typography variant="body2" color="text.secondary" paragraph>
                🏢 {person.businessName}
                {person.industry ? ` · ${person.industry}` : ''}
              </Typography>
            )}
            {person.interests.length > 0 && (
              <Box sx={{ mb: 2 }}>
                <Typography variant="subtitle2" gutterBottom>
                  Into
                </Typography>
                <Box sx={{ display: 'flex', gap: 0.75, flexWrap: 'wrap' }}>
                  {person.interests.map(interest => (
                    <Chip key={interest} label={interest} size="small" variant="outlined" />
                  ))}
                </Box>
              </Box>
            )}
            <Typography variant="subtitle2" gutterBottom>
              Their navitar
            </Typography>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
              {art ? (
                <NavitarArtImg
                  src={art}
                  alt={`${person.navitarName} art`}
                  element={person.navitarElement}
                  style={{
                    width: 72,
                    height: 72,
                    borderRadius: '50%',
                    border: `3px solid ${elementColor(person.navitarElement)}`,
                    flexShrink: 0,
                  }}
                />
              ) : (
                <Box
                  sx={{
                    width: 72,
                    height: 72,
                    borderRadius: '50%',
                    border: `3px solid ${elementColor(person.navitarElement)}`,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    fontSize: '2rem',
                    flexShrink: 0,
                  }}
                >
                  {elementEmoji(person.navitarElement)}
                </Box>
              )}
              <Box>
                <Typography variant="body1">
                  {person.navitarName}{' '}
                  <Chip label={person.navitarElement} size="small" sx={{ ml: 0.5 }} />
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  Level {person.navitarLevel}
                </Typography>
                <Box sx={{ mt: 0.5, display: 'flex', gap: 0.5, flexWrap: 'wrap' }}>
                  {person.navitarSkills.map(skill => (
                    <Chip key={skill} label={skill} size="small" variant="outlined" />
                  ))}
                </Box>
              </Box>
            </Box>
          </DialogContent>
          <DialogActions>
            <Button onClick={onClose}>Close</Button>
          </DialogActions>
        </>
      )}
    </Dialog>
  );
};
