// Station collecting — the ONE collect flow every refill
// station uses (Round 36.9 Part 9 extracted it from RealmMap so
// the Map and Stroll run literally the same logic, as Eddie's
// "behaviour is IDENTICAL" order requires).
//
// Collecting grants 2–3 potions as a random mix of the three
// types, rolls the §11 item drops (emerald ~1-in-3, shield
// 1-in-5, crystal 1-in-10), clamps EVERYTHING to the Inventory
// Bag's headroom so grants never overflow, and starts the
// station's 5-minute cooldown — persisted per station in
// localStorage, so a reload doesn't reset it. A full bag
// collects nothing and does NOT start the cooldown. The result
// message lists exactly what landed.
import type { RefillStation } from '../data/stations';
import { getPotions, grantPotions, POTIONS, type PotionCounts, type PotionId } from './potions';
import {
  getItems,
  grantItems,
  rollStationItemDrops,
  bagHeadroom,
  ITEMS,
  type ItemCounts,
  type ItemId,
} from './items';

export const STATION_COOLDOWNS_KEY = 'glacer-station-cooldowns';
export const STATION_COOLDOWN_MS = 5 * 60 * 1000;

export function loadStationCooldowns(): Record<string, number> {
  try {
    const raw = localStorage.getItem(STATION_COOLDOWNS_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw) as Record<string, unknown>;
    const out: Record<string, number> = {};
    Object.entries(parsed).forEach(([k, v]) => {
      if (typeof v === 'number' && Number.isFinite(v)) out[k] = v;
    });
    return out;
  } catch {
    return {};
  }
}

export function stationCooldownLeft(
  cooldowns: Record<string, number>,
  stationId: string,
  now: number = Date.now()
): number {
  return Math.max(0, (cooldowns[stationId] ?? 0) - now);
}

export interface StationCollectResult {
  /** True when a collect actually landed (and the cooldown started). */
  granted: boolean;
  /** The exact line the station card shows. */
  message: string;
  potions: PotionCounts;
  items: ItemCounts;
  cooldowns: Record<string, number>;
}

export function collectStation(station: RefillStation): StationCollectResult {
  const cooldowns = loadStationCooldowns();
  if (bagHeadroom() <= 0) {
    return {
      granted: false,
      message: '🎒 Bag full — spend or use some items before collecting.',
      potions: getPotions(),
      items: getItems(),
      cooldowns,
    };
  }
  let headroom = bagHeadroom();
  const wanted = 2 + Math.floor(Math.random() * 2);
  const total = Math.min(wanted, headroom);
  const grant: Partial<PotionCounts> = {};
  const ids: PotionId[] = ['health', 'recharge', 'power'];
  for (let i = 0; i < total; i++) {
    const id = ids[Math.floor(Math.random() * ids.length)];
    grant[id] = (grant[id] ?? 0) + 1;
  }
  const potions = grantPotions(grant);
  headroom -= total;
  const drops = rollStationItemDrops();
  const itemGrant: Partial<ItemCounts> = {};
  (Object.keys(drops) as ItemId[]).forEach(id => {
    if (drops[id] > 0 && headroom > 0) {
      itemGrant[id] = 1;
      headroom -= 1;
    }
  });
  if (Object.keys(itemGrant).length > 0) grantItems(itemGrant);
  const parts: string[] = [];
  (Object.keys(grant) as PotionId[]).forEach(id => {
    if (grant[id]) parts.push(`${POTIONS[id].emoji} ${POTIONS[id].name} ×${grant[id]}`);
  });
  (Object.keys(itemGrant) as ItemId[]).forEach(id => {
    parts.push(`${ITEMS[id].emoji} ${ITEMS[id].name} ×${itemGrant[id]}`);
  });
  const next = { ...cooldowns, [station.id]: Date.now() + STATION_COOLDOWN_MS };
  try {
    localStorage.setItem(STATION_COOLDOWNS_KEY, JSON.stringify(next));
  } catch {
    // Private mode / quota: the cooldown still holds for this
    // session through the caller's state.
  }
  return {
    granted: true,
    message: `Collected: ${parts.join(' · ')}`,
    potions,
    items: getItems(),
    cooldowns: next,
  };
}
